package macro;
import star.common.*;import star.metrics.*;import star.base.report.*;import star.flow.*;import star.material.*;import star.segregatedflow.*;import star.turbulence.*;import star.kwturb.*;import java.nio.file.*;import java.util.*;
public class BuildMini extends StarMacro {
void scalar(ScalarProfile p,double v){p.setMethod(ConstantScalarProfileMethod.class);p.getMethod(ConstantScalarProfileMethod.class).getQuantity().setValue(v);}
public void execute(){Simulation s=getActiveSimulation();Path r=Paths.get(System.getenv("MINI_CASE_DIR"));try{
if(s.getNumberOfGpgpus()!=0||s.getRegionManager().getRegions().size()!=0)throw new IllegalStateException("Fresh CPU-only session required");
s.getImportManager().importMeshFiles(r.resolve("mesh_2d.msh").toString());List<Region> rs=new ArrayList<>(s.getRegionManager().getRegions());if(rs.size()!=1)throw new IllegalStateException("One fluid region required");
PhysicsContinuum pc=s.getContinuumManager().createContinuum(PhysicsContinuum.class);pc.setPresentationName("L1 true2D water steady SST");pc.enable(TwoDimensionalModel.class);pc.enable(SteadyModel.class);pc.enable(SingleComponentLiquidModel.class);pc.enable(SegregatedFlowModel.class);pc.enable(ConstantDensityModel.class);pc.enable(TurbulentModel.class);pc.enable(RansTurbulenceModel.class);pc.enable(KOmegaTurbulence.class);pc.enable(SstKwTurbModel.class);pc.enable(KwAllYplusWallTreatment.class);
Material water=pc.getModelManager().getModel(SingleComponentLiquidModel.class).getMaterial();water.getMaterialProperties().getMaterialProperty(ConstantDensityProperty.class).setConstant(1000);water.getMaterialProperties().getMaterialProperty(DynamicViscosityProperty.class).setConstant(.001);pc.getReferenceValues().get(ReferencePressure.class).setValue(120736.226);
pc.getInitialConditions().get(VelocityProfile.class).getMethod(ConstantVectorProfileMethod.class).getQuantity().setComponents(18,0,0);pc.getInitialConditions().get(KwTurbSpecOption.class).setSelected(KwTurbSpecOption.Type.INTENSITY_VISCOSITY_RATIO);scalar(pc.getInitialConditions().get(TurbulenceIntensityProfile.class),.001);scalar(pc.getInitialConditions().get(TurbulentViscosityRatioProfile.class),10);
List<Boundary> walls=new ArrayList<>(),flap=new ArrayList<>();StringBuilder bs=new StringBuilder();for(Region reg:rs){reg.setPhysicsContinuum(pc);for(Boundary b:reg.getBoundaryManager().getBoundaries()){String n=b.getPresentationName();bs.append(n+" "+b.getBoundaryType()+"\n");if(n.contains("main")||n.contains("flap")){b.setBoundaryType(WallBoundary.class);walls.add(b);if(n.contains("flap"))flap.add(b);}else if(n.contains("inlet")){b.setBoundaryType(InletBoundary.class);b.getConditions().get(InletVelocityOption.class).setSelected(InletVelocityOption.Type.COMPONENTS);b.getValues().get(VelocityProfile.class).getMethod(ConstantVectorProfileMethod.class).getQuantity().setComponents(18,0,0);b.getConditions().get(KwTurbSpecOption.class).setSelected(KwTurbSpecOption.Type.INTENSITY_VISCOSITY_RATIO);scalar(b.getValues().get(TurbulenceIntensityProfile.class),.001);scalar(b.getValues().get(TurbulentViscosityRatioProfile.class),10);}else if(n.contains("outlet")){b.setBoundaryType(PressureBoundary.class);scalar(b.getValues().get(StaticPressureProfile.class),0);}else if(n.contains("farfield"))b.setBoundaryType(SymmetryBoundary.class);else throw new IllegalStateException("Unexpected boundary "+n);}}
if(walls.size()!=2||flap.size()!=1)throw new IllegalStateException("Main/flap wall labels missing");pc.getModelManager().getModel(SegregatedFlowModel.class).getUpwindOption().setSelected(FlowUpwindOption.Type.SECOND_ORDER);pc.getModelManager().getModel(SstKwTurbModel.class).getUpwindOption().setSelected(UpwindOption.Type.SECOND_ORDER);
for(int i=0;i<2;i++){ForceReport f=s.getReportManager().createReport(ForceReport.class);f.setPresentationName(i==0?"MINI_Fx":"MINI_Fy");f.setPressureOption(FluidLoadsReportPressureOption.SP_UC);f.getDirection().setComponents(i==0?1:0,i==1?1:0,0);f.getParts().setObjects(walls);f.createMonitor();}
MomentReport mh=s.getReportManager().createReport(MomentReport.class);mh.setPresentationName("MINI_Mh");mh.setPressureOption(FluidLoadsReportPressureOption.SP_UC);mh.getDirection().setComponents(0,0,-1);mh.getOrigin().setComponents(.952,.02128173276776986,0);mh.getParts().setObjects(flap);mh.createMonitor();
for(String name:List.of("CL","CD")){ExpressionReport e=s.getReportManager().createReport(ExpressionReport.class);e.setPresentationName("MINI_"+name);e.setDefinition("${MINI_"+(name.equals("CL")?"Fy":"Fx")+"Report}/<192780 N>");e.createMonitor();}
for(String ff:List.of("AbsolutePressure","CellQuality","FaceValidity","Volume")){MinReport m=s.getReportManager().createReport(MinReport.class);m.setPresentationName("MINI_min_"+ff);m.setFieldFunction(s.getFieldFunctionManager().getFunction(ff));m.getParts().setObjects(rs);m.setSmooth(false);}
UserFieldFunction cp=s.getFieldFunctionManager().createFieldFunction();cp.setFunctionName("MINI_Cp");cp.setPresentationName("MINI_Cp");cp.setDefinition("$Pressure/<162000 Pa>");cp.getTypeOption().setSelected(FieldFunctionTypeOption.Type.SCALAR);
XyzInternalTable tab=s.getTableManager().createTable(XyzInternalTable.class);tab.setPresentationName("MINI Cp walls");tab.getParts().setObjects(walls);tab.setFieldFunctions(List.of(cp,s.getFieldFunctionManager().getFunction("WallYplus")));
s.getSimulationIterator().getAutoSave().setEnabled(false);Files.writeString(r.resolve("native_boundaries.txt"),bs.toString());long nc=((FvRepresentation)s.getRepresentationManager().getObject("Volume Mesh")).getCellCount();s.saveState(r.resolve("MINI_prepared.sim").toString());Files.writeString(r.resolve("BUILD_STATUS.json"),"{\"status\":\"BUILT_NOT_SOLVED\",\"cells\":"+nc+",\"true_2D\":true,\"SST\":true,\"VOF\":false,\"Overset\":false,\"fields_initialized\":false,\"solver_iterations\":0}");
}catch(Exception e){try{Files.writeString(r.resolve("BUILD_ERROR.txt"),e.toString());}catch(Exception ignored){}throw new RuntimeException(e);}}
}
